import sys,collections
POS={"happy","great","good","excited","proud","calm","love"}
NEG={"sad","tired","stressed","anxious","angry","bad","lost"}
def analyze(t):
    w=[x.strip(".,!?").lower() for x in t.split()]
    p=sum(x in POS for x in w);n=sum(x in NEG for x in w)
    mood="positive" if p>n else "negative" if n>p else "neutral"
    top=collections.Counter(x for x in w if len(x)>4).most_common(3)
    return {"mood":mood,"themes":[k for k,_ in top],"nudge":"Take a 5-min breather." if mood=="negative" else "Keep the momentum."}
